  const rows = [['Material', esc(s.material)], ['Finish', esc(s.finish)], ['Colour', (s.hex || s.colourName) ? `<span class="row">${s.hex ? `<i class="sw" style="background:${esc(s.hex)}"></i>` : ''}${esc(s.colourName)} ${s.hex ? `<span class="mono muted small">${esc(s.hex)}</span>` : ''}</span>` : ''], ['Source', s.link ? `<a href="${esc(s.link)}" target="_blank" rel="noopener">${esc(domain(s.link))} ↗</a>` : '']].filter(r => r[1]);
  return (rows.length ? `<div class="sec"><div class="lbl">Specification</div><dl class="spec">${rows.map(r => `<dt>${r[0]}</dt><dd>${r[1]}</dd>`).join('')}</dl></div>` : '') +
    ((e.dims || []).length ? `<div class="sec"><div class="lbl">Dimensions & levels</div><table class="dims">${e.dims.map(d => `<tr><td>${esc(d.k)}${SRC[d.src] ? `<span class="src">${SRC[d.src]}</span>` : ''}</td><td>${esc(d.v)}</td></tr>`).join('')}</table></div>` : '') +
    (e.notes ? `<div class="sec"><div class="lbl">Notes for the modeler</div><p>${esc(e.notes)}</p></div>` : '');
